from pathlib import Path
import json
R=Path(__file__).parent
OLD=json.loads((R.parent/'dauroh-v6-id/slides-id.json').read_text())
S=[];day=1;chapter='Pembukaan';bab=0
REF={
'gem':['https://support.google.com/gemini/answer/16275805?hl=en','https://gemini.google/overview/canvas/','https://gemini.google/overview/deep-research/'],
'chat':['https://help.openai.com/en/articles/9260256-chatgpt-capabilities-overview','https://help.openai.com/en/articles/11780217-study-mode','https://help.openai.com/en/articles/10169521-projects-in-chatgpt'],
'perp':['https://www.perplexity.ai/help-center/en/articles/10738684-what-is-research-mode','https://www.perplexity.ai/help-center/en/articles/10352961-what-are-projects'],
'deep':['https://api-docs.deepseek.com/guides/thinking_mode','https://api-docs.deepseek.com/updates/'],
'claude':['https://support.claude.com/en/articles/11088861-use-research-on-claude','https://support.claude.com/en/articles/9487310-what-are-artifacts-and-how-do-i-use-them'],
'sources':['https://archive.org/','https://www.noor-book.com/contact-us','https://shamela.ws/','https://www.waqfeya.net/'],
}
def add(title,body,notes,kind='rows',**kw):
 d=dict(id=len(S)+1,day=day,bab=bab,chapter=chapter,title=title,body=body,notes=notes.strip(),kind=kind,**kw);S.append(d);return d

def reuse(n,kind='rows',title=None,body=None,extra=''):
 o=OLD[n-1];return add(title or o['title'],body or o['body'],o['notes']+'\n\n'+extra,kind,old=n,prompt=o.get('demo',''))
def chap(num,name,question,goals,old=None,notes=''):
 global chapter,bab
 chapter=name;bab=num
 if old:notes=notes+'\n\n'+OLD[old-1]['notes']
 return add(name,[question,goals],notes,'chapter')
def feature(title,items,notes,prompt,steps,ref):
 return add(title,items,notes+'\n\nSaya perlihatkan langkahnya sambil menyebut tujuan setiap langkah. '+steps+'\n\nKalimat yang saya gunakan dalam demonstrasi adalah: “'+prompt+'”\n\nSesudah jawaban muncul, kita baca satu bagian bersama. Saya meminta seorang peserta menunjukkan bagian yang memenuhi permintaan dan bagian yang masih perlu diperjelas. Jika hasilnya berbeda dari contoh, kita periksa bahan dan instruksinya. Perbedaan jawaban menjadi kesempatan belajar untuk melanjutkan percakapan dengan lebih terarah.', 'feature',prompt=prompt,refs=REF[ref])
def task(title,minutes,steps,result,notes,question):
 return add(title,steps,notes+'\n\nWaktu yang tersedia adalah '+str(minutes)+' menit. Hasil yang perlu Anda simpan adalah '+result+' Saya akan mengingatkan ketika waktu tinggal dua menit supaya kita sempat menutup pekerjaan dengan rapi. Jika belum punya akun atau aksesnya bermasalah, kerjakan berpasangan. Satu orang mengoperasikan perangkat, satu orang membaca hasil dan mencatat keputusan. Keduanya perlu memahami alasan di balik revisinya.\n\nSetelah latihan, kita bahas pertanyaan ini: '+question+' Saya memilih dua contoh untuk dibaca bersama. Kita membicarakan langkah yang membuat hasilnya lebih baik, lalu menyimpan hasil yang bisa digunakan pada bagian berikutnya.','exercise',minutes=minutes,result=result)
add('AI untuk belajar dan penelitian',['Dauroh dua hari','Dari penggunaan pertama sampai pekerjaan bahsul ilmi'],OLD[0]['notes'],'cover')
add('Peta dauroh',['Hari 1: dasar AI, lima aplikasi, dan rumus prompt','Hari 2: pengumpulan sumber, proses penelitian, dan tur OpenTurath'],OLD[1]['notes']+'\n\nSetiap bab aplikasi berakhir dengan tugas singkat. Anda boleh mencoba dengan bahasa Arab sejak awal. Pada pertemuan ini, bahasa Indonesia dipakai dalam draf bahan pengajar untuk memudahkan perbaikan isi. Tugas kita akan menghasilkan beberapa bahan kecil yang saling berhubungan. Jadwal belajar menjadi latihan pertama, kemudian keterampilan yang sama dipakai untuk mengatur pekerjaan penelitian.','agenda')
chap(1,'Mengenal AI','Apa yang sebenarnya sedang kita gunakan?','Pengertian, sejarah singkat, cara kerja, dan batas kemampuan',old=3,notes='Kita mulai dengan gambaran yang paling dasar. Saya ingin Anda nyaman bertanya, termasuk tentang hal yang mungkin terasa terlalu sederhana. Setelah bab ini, nama aplikasi dan nama fitur akan lebih mudah dipahami. Kita belum perlu memilih aplikasi yang paling hebat. Kita perlu tahu apa yang sedang kita minta dan mengapa hasilnya tetap harus dibaca.')
for n,kind in [(4,'definition'),(5,'rows'),(6,'timeline'),(7,'definition'),(8,'compare'),(9,'definition'),(10,'workflow'),(11,'compare'),(12,'quote'),(13,'compare')]:reuse(n,kind)
chap(2,'Gemini','Percakapan, berkas, dan ruang kerja','Tujuan bab: mencoba satu tugas, mengubah hasil, lalu menyimpannya',old=16,notes='Aplikasi pertama yang kita coba adalah Gemini dari Google. Di bab ini kita membedakan percakapan biasa, pekerjaan atas berkas, Canvas, dan Deep Research. Fitur yang muncul dapat berbeda menurut akun atau wilayah. Cukup ikuti jalur yang tersedia pada perangkat Anda. Saya akan memberikan tugas yang tetap bisa dikerjakan melalui percakapan biasa.')
feature('Fitur dasar Gemini',[['Percakapan','Bertanya, meminta penjelasan, lalu menindaklanjuti jawaban.'],['Berkas dan gambar','Memberi bahan yang akan dibaca atau dibandingkan.'],['Live','Percakapan suara ketika tersedia pada perangkat.']],'''Kita kenali bagian yang paling sering dipakai lebih dahulu. Kotak pesan adalah tempat menjelaskan pekerjaan. Tombol lampiran memberi bahan tambahan, misalnya catatan atau gambar halaman. Berbicara melalui Live bisa membantu bertanya secara lisan, tetapi bahan penelitian tetap perlu disimpan agar kita dapat memeriksanya kembali.

Misalkan saya mempunyai catatan pelajaran yang campur aduk. Saya tidak langsung meminta penelitian lengkap. Saya menempelkan catatan yang boleh dibagikan dan meminta susunan yang lebih mudah dibaca. Setelah itu saya bertanya, bagian mana yang masih belum jelas. Dengan begitu, percakapan memiliki arah.

Bila masukan berupa foto halaman Arab, hasil pembacaan mungkin keliru pada nama, angka, atau kata yang menentukan makna. Kita cocokkan dengan gambar aslinya sebelum memakai hasilnya. Nama fitur dan letak tombol dapat berubah, jadi yang perlu Anda ingat adalah fungsi yang ingin dipakai.''','Rapikan catatan berikut menjadi urutan belajar. Pertahankan seluruh istilah. Pisahkan informasi yang jelas dan hal yang masih perlu saya lengkapi. [Tempel catatan sendiri.]','Saya membuka percakapan baru, menunjukkan kotak pesan, kemudian menunjukkan tempat melampirkan berkas. Untuk latihan awal, saya cukup menempelkan teks agar semua peserta dapat mengikuti.','gem')
feature('Canvas: tempat menyunting hasil',[['Kapan berguna','Ketika sebuah draf perlu diperbaiki beberapa kali.'],['Cara bekerja','Buat draf, pilih bagian, minta perubahan tertentu.'],['Hasil yang dicari','Naskah yang lebih jelas dengan makna tetap terjaga.']],'''Canvas membantu kita bekerja pada sebuah hasil yang berkembang. Bayangkan Anda sudah mempunyai pembukaan tulisan, tetapi urutannya belum enak dibaca. Kita bisa meminta bantuan menyunting satu bagian, kemudian membaca perubahan sebelum menerima hasilnya.

Saya ingin Anda memperhatikan perbedaan antara meminta sebuah jawaban baru dan memperbaiki sebuah draf. Kalau persoalannya hanya ada pada paragraf kedua, sebutkan paragraf itu. Kita tidak perlu mengganti seluruh tulisan. Saya juga menyebutkan unsur yang harus dipertahankan, seperti istilah khusus, kutipan, dan tingkat kepastian sebuah pendapat.

Canvas juga dapat dipakai membuat bahan interaktif, tetapi pada dauroh ini kita fokus pada penyuntingan naskah. Fasilitas tambahan bisa dijelajahi setelah peserta memahami cara membaca dan mengendalikan perubahan. Tampilan yang menarik tidak membuktikan bahwa penjelasannya benar. Kita tetap menilai isi yang muncul.''','Bantu susun pengantar 120 kata dari catatan saya. Sesudah itu, perbaiki hanya paragraf pertama agar lebih jelas. Jangan menambah fakta atau kutipan. [Tempel catatan.]','Saya memilih Canvas jika tersedia, membuat draf pendek, lalu meminta satu revisi yang batasnya jelas. Kita bandingkan kalimat sebelum dan sesudah perubahan.','gem')
feature('Deep Research: penelusuran bertahap',[['Masukan','Pertanyaan, cakupan, dan jenis sumber yang dicari.'],['Proses','Tinjau rencana penelusuran sebelum melanjutkan.'],['Pemeriksaan','Buka sumber dan cek apakah mendukung isi laporan.']],'''Kadang pertanyaan kita membutuhkan penelusuran melalui beberapa sumber. Deep Research dapat membantu menyusun rencana dan menjalankan penelusuran tersebut. Kita perlu memberi batas supaya laporan yang dihasilkan tidak melebar ke mana-mana.

Contoh tugasnya adalah mencari penelitian tentang cara mahasiswa mengulang pelajaran. Saya menentukan bahwa yang dicari adalah artikel penelitian dan pedoman perguruan tinggi, bukan unggahan motivasi. Sebelum laporan berjalan, saya membaca rencana yang ditawarkan. Jika cakupannya terlalu luas, saya mempersempitnya.

Setelah laporan selesai, saya memilih satu pernyataan dan membuka sumbernya. Kita memeriksa siapa penulisnya, apa bentuk penelitiannya, dan bagian mana yang benar-benar mendukung pernyataan tersebut. Tautan yang banyak belum cukup. Bila fitur tidak tersedia pada akun peserta, mereka dapat berlatih membuat rencana pencarian melalui percakapan biasa dan membuka hasil pencarian sendiri.''','Cari bahan tentang strategi mengulang pelajaran untuk mahasiswa. Utamakan penelitian atau pedoman universitas. Tampilkan rencana pencarian terlebih dahulu dan jelaskan jenis sumber yang akan dipakai.','Saya memperlihatkan pilihan Deep Research bila tersedia. Kita baca rencananya, kemudian saya tunjukkan cara membuka salah satu sumber pada laporan.','gem')
add('Contoh percakapan Gemini',['Permintaan awal: “Bantu saya belajar.”','Perbaikan: “Susun pengulangan tiga bab dalam enam hari, 45 menit setiap hari.”','Tindak lanjut: “Bab kedua paling sulit. Ubah pembagian waktunya.”'],OLD[28]['notes']+'\n\nSaya memakai contoh yang sama sebelum dan sesudah memberi keterangan. Peserta melihat bahwa hasil berubah ketika kebutuhan dijelaskan. Kita belum menghafal rumus prompt pada tahap ini. Kita sedang mengalami alasan mengapa sebuah permintaan perlu diperjelas.','prompt')
task('Eksplorasi Gemini',10,['Susun jadwal mengulang tiga bab selama enam hari.','Tambahkan satu kondisi yang belum Anda sebutkan.','Minta satu perbaikan dan simpan jawaban akhirnya.'],'jadwal yang sudah direvisi dan satu kalimat alasan perubahannya.', '''Sekarang giliran Anda. Gunakan tiga bab yang benar-benar sedang dipelajari. Kalau belum ingin menyebut nama kitab, cukup tulis bab pertama, kedua, dan ketiga. Tentukan waktu belajar yang realistis. Kita tidak sedang mencari jadwal yang paling indah, tetapi jadwal yang mungkin dijalankan.

Baca jawaban pertama sebelum mengirim pesan kedua. Perhatikan apakah waktu harian sesuai batas dan apakah bagian sulit mendapat perhatian yang cukup. Setelah itu, tambahkan satu keadaan nyata, misalnya satu hari Anda mempunyai kegiatan lain. Minta Gemini memperbaiki bagian yang terkena perubahan.

Saat berkeliling, saya ingin mendengar alasan Anda mengubah jadwal. Jika hasilnya terasa umum, tunjukkan informasi apa yang belum diberikan. Anda boleh memakai percakapan biasa tanpa Canvas atau fitur berbayar.''','Informasi tambahan apa yang paling mengubah jadwal Anda?')
chap(3,'ChatGPT','Percakapan yang membantu belajar','Tujuan bab: bekerja dengan bahan dan memeriksa pemahaman',old=14,notes='Kita beralih ke ChatGPT. Anda sudah mempunyai pengalaman pertama melalui Gemini, jadi langkah dasarnya akan terasa akrab. Kali ini fokus kita adalah memberi bahan yang jelas, memakai percakapan untuk belajar, dan menjaga pekerjaan tetap teratur. Hasil latihan Gemini tetap disimpan sebagai pembanding.')
feature('Bahan, pencarian, dan percakapan',[['Berkas atau gambar','Untuk pertanyaan tentang bahan yang Anda sertakan.'],['Search','Untuk mencari informasi luar dengan tautan sumber.'],['Percakapan lanjutan','Untuk memperjelas atau memperbaiki satu bagian.']],'''Ketika menggunakan ChatGPT, tentukan dahulu dari mana informasi untuk tugas itu harus diambil. Jika kita meminta ringkasan catatan pribadi, bahan utamanya adalah catatan yang diberikan. Jika kita menanyakan informasi terbaru, pencarian web menjadi relevan. Dua pekerjaan itu membutuhkan masukan dan cara pemeriksaan yang berbeda.

Saya mencoba sebuah paragraf catatan terlebih dahulu. Kita meminta isi pokoknya dan bagian yang belum lengkap. Setelah itu saya menunjukkan contoh pertanyaan yang memerlukan pencarian luar. Pada jawaban yang memuat tautan, saya membuka satu tautan untuk memeriksa isi aslinya.

Bila peserta memakai gambar halaman, sebutkan bagian yang hendak dibaca. Jangan menganggap seluruh halaman selalu terbaca dengan benar. Pada nama tokoh, angka, dan kutipan, pembandingan dengan bahan asli tetap diperlukan. Kita juga menghindari mengunggah dokumen pribadi atau pekerjaan orang lain tanpa dasar yang jelas.''','Dari catatan berikut, sebutkan gagasan utama dan bagian yang belum jelas. Gunakan hanya catatan ini. Jangan melengkapi kekurangan dengan fakta dari luar. [Tempel catatan.]','Saya menunjukkan lampiran berkas, menempelkan teks pendek, lalu mengirim satu pertanyaan lanjutan yang menunjuk bagian tertentu.','chat')
feature('Study mode: belajar melalui pertanyaan',[['Tujuan','Membantu memahami langkah dan menguji pemahaman.'],['Interaksi','Coba menjawab pertanyaan sebelum meminta penjelasan.'],['Tanda kemajuan','Anda bisa menjelaskan kembali dengan kata sendiri.']],'''Study mode dapat membantu ketika kita ingin belajar melalui tanya jawab yang bertahap. Saya memberi tahu tingkat pengetahuan saya dan apa yang sedang ingin dipahami. Kita dapat memakai sebuah konsep yang sudah cukup akrab, supaya mudah menilai apakah penjelasannya masuk akal.

Sebagai contoh, saya ingin memahami perbedaan topik dan pertanyaan penelitian. Saya meminta ChatGPT menanyakan satu hal terlebih dahulu. Setelah saya menjawab, baru ia memberi tanggapan atau contoh. Tujuannya supaya saya ikut berpikir selama percakapan berlangsung.

Kalau nama Study mode tidak muncul pada akun yang digunakan, pola belajar serupa dapat diminta lewat instruksi percakapan. Ketersediaan fitur tetap mengikuti akun dan pengaturan. Jangan menggabungkan semua fasilitas seolah selalu tersedia dalam setiap ruang kerja. Setelah selesai, saya menutup percakapan sejenak dan mencoba menjelaskan kembali konsepnya tanpa membaca jawaban.''','Bantu saya memahami perbedaan topik dan pertanyaan penelitian. Tanyakan satu pertanyaan setiap kali. Tunggu jawaban saya, lalu berikan koreksi dan contoh yang sederhana.','Saya membuka mode belajar jika tersedia. Saya menjawab pertanyaan pertama dengan sengaja belum lengkap, lalu membaca koreksi dan memperbaiki jawaban saya.','chat')
feature('Projects dan Canvas',[['Projects','Mengelompokkan percakapan, berkas, dan instruksi yang berkaitan.'],['Canvas','Menyunting draf yang perlu diperbaiki bertahap.'],['Pilihan awal','Gunakan satu percakapan biasa jika pekerjaan masih sederhana.']],'''Projects berguna untuk pekerjaan yang dilanjutkan dalam beberapa pertemuan. Misalnya, satu proyek berisi pertanyaan penelitian, catatan bacaan, dan beberapa percakapan mengenai topik yang sama. Instruksi proyek membantu menjelaskan aturan yang ingin dipakai secara konsisten.

Canvas mempunyai fungsi yang lebih dekat dengan pekerjaan menyunting sebuah hasil. Kita melihat draf, menunjuk bagian, lalu meminta perbaikan tertentu. Kedua fasilitas ini membantu pengorganisasian, tetapi kita tetap perlu mengetahui berkas yang dipakai dan perubahan yang terjadi.

Saya tidak mewajibkan peserta membuat proyek hari ini. Untuk latihan pertama, satu percakapan biasa sudah cukup. Jika nanti penelitian Anda berlangsung beberapa minggu, barulah pengorganisasian seperti ini terasa manfaatnya. Fitur tertentu dapat berbeda antarjenis akun. Misalnya, mode belajar tidak perlu diasumsikan berjalan di dalam percakapan proyek. Kita menyesuaikan langkah dengan fasilitas yang benar-benar tersedia.''','Untuk pekerjaan ini, gunakan catatan yang saya berikan dan pertahankan istilahnya. Jika ada keterangan yang kurang, tanyakan kepada saya sebelum membuat draf.','Saya menjelaskan contoh nama proyek dan isi berkasnya. Lalu saya menunjukkan satu draf pendek yang diperbaiki pada bagian tertentu, bila Canvas tersedia.','chat')
task('Praktik ChatGPT',10,['Tempelkan satu paragraf catatan belajar.','Minta penjelasan, lalu minta satu pertanyaan untuk menguji pemahaman.','Jawab dengan kata sendiri dan simpan satu koreksi.'],'paragraf awal, jawaban Anda sendiri, dan satu perbaikan pemahaman.', '''Pada latihan ini, pilih catatan yang cukup pendek untuk dibaca bersama. Gunakan bahan yang boleh dibagikan. Kita tidak perlu mengunggah satu kitab penuh. Saya ingin Anda melihat hubungan yang jelas antara bahan yang diberikan dan pertanyaan yang diajukan.

Setelah menerima penjelasan, minta satu pertanyaan untuk menguji pemahaman. Coba jawab tanpa menyalin kalimat dari layar. Jika Anda belum bisa menjawab, tunjukkan bagian yang masih membingungkan. Minta penjelasan dengan contoh yang lebih dekat dengan pelajaran Anda.

Ketika membahas hasil, kita akan memperhatikan apakah koreksi ChatGPT sesuai dengan catatan. Jika muncul penjelasan tambahan yang belum ada pada bahan, tandai sebagai tambahan untuk diperiksa. Latihan ini selesai ketika Anda bisa menyebutkan satu hal yang kini lebih dipahami dan alasan mengapa penjelasan itu membantu.''','Apakah Anda dapat menjelaskan kembali isi catatan tanpa membaca jawaban AI?')
add('Istirahat',['15 menit','Sesudah istirahat: pencarian dengan Perplexity, lalu DeepSeek dan Claude.'],'''Kita berhenti selama lima belas menit. Sebelum beranjak, simpan percakapan atau salin hasil yang ingin digunakan kembali. Pastikan catatan latihan tidak hilang karena halaman tertutup. Bagi yang perangkatnya bermasalah, gunakan waktu ini untuk berpasangan dengan peserta lain.

Sampai di sini kita sudah mencoba dua aplikasi melalui tugas sederhana. Anda tidak perlu menghafal seluruh nama fitur. Ingat pengalaman yang sudah dilakukan: menjelaskan kebutuhan, memberi bahan, membaca jawaban, lalu meminta perbaikan tertentu. Nanti rumus prompt akan membantu kita merapikan kebiasaan tersebut.

Setelah istirahat, kita akan melihat aplikasi yang lebih menonjolkan pencarian dan rujukan. Hasil latihan yang telah disimpan tidak perlu diulang dari awal. Kita akan menambahkan keterampilan membuka sumber dan memeriksa apakah sumber tersebut mendukung penjelasan yang diberikan.

Saya akan melanjutkan tepat setelah waktu istirahat selesai. Jika masih ada pertanyaan mengenai langkah dasar, catat satu kalimat agar kita dapat menjawabnya tanpa mengulang seluruh demonstrasi. Pertanyaan mengenai penelitian yang lebih luas akan kita bawa ke hari kedua, ketika bahan, sumber, dan tujuan penelitian mulai disusun secara lebih teratur.''','break')
chap(4,'Perplexity','Pencarian dengan rujukan yang dapat dibuka','Tujuan bab: menemukan dua sumber dan memeriksa satu klaim',notes='''Sekarang kita mengenal Perplexity. Alat ini membantu menelusuri informasi dan menyajikan jawaban dengan rujukan. Pada bab ini, perhatian kita bukan pada banyaknya tautan. Kita akan mempraktikkan bagaimana sebuah tautan dibuka dan bagaimana isi sumber dibandingkan dengan kalimat dalam jawaban.

Bayangkan Anda ingin mencari bahan awal mengenai satu topik. Perplexity dapat membantu menemukan jalan masuk dan merangkum beberapa hasil. Namun sebuah ringkasan dapat terlalu menyederhanakan, memakai sumber yang kurang tepat, atau menarik kesimpulan yang lebih kuat daripada isi sumbernya. Karena itu, kita menggabungkan pencarian dengan pembacaan langsung.

Saya akan memakai pertanyaan sederhana agar kita dapat menilai hasilnya bersama. Kita meminta jenis sumber yang jelas, lalu memilih dua sumber yang benar-benar dapat diakses. Setelah itu, kita periksa satu klaim saja dengan teliti. Latihan kecil ini lebih mudah diikuti daripada menerima laporan panjang tanpa mengetahui asal keterangannya.

Nama fitur pengorganisasian dapat berubah. Dokumentasi yang kita periksa saat menyusun bahan ini memakai nama Projects untuk ruang kerja yang sebelumnya dikenal sebagai Spaces. Yang perlu Anda pahami adalah fungsinya: menyimpan pencarian dan bahan yang berkaitan dalam satu pekerjaan. Kita tidak memerlukan langganan tertentu untuk memahami alur pemeriksaannya.''')
feature('Membaca jawaban beserta sumbernya',[['Pertanyaan','Sebutkan kebutuhan dan jenis bahan yang dicari.'],['Rujukan','Buka sumber yang mendasari pernyataan penting.'],['Kecocokan','Bandingkan makna jawaban dengan isi halaman asal.']],'''Tampilan jawaban yang disertai rujukan memberi kesempatan untuk memeriksa informasi lebih cepat. Kita tetap perlu menggunakan kesempatan itu. Saya mulai dengan pertanyaan tentang strategi mengulang pelajaran dan meminta bahan dari penelitian atau pedoman perguruan tinggi.

Sesudah hasil muncul, saya memilih satu kalimat yang cukup spesifik. Kita cari rujukan yang menyertainya, lalu membuka halaman asal. Apakah sumber itu benar-benar menjelaskan hal yang sama? Apakah kalimat dalam jawaban mengubah kemungkinan menjadi kepastian? Apakah konteks penelitiannya sesuai dengan mahasiswa yang sedang kita bicarakan?

Kalau sumber berupa tulisan populer yang meringkas penelitian lain, catat bahwa kita masih berjarak dari penelitian asal. Kita bisa memakai informasi itu sebagai petunjuk untuk mencari lebih jauh. Jangan langsung mengutip ringkasan seolah kita sudah membaca artikel penelitian aslinya. Di hari kedua, cara ini akan dipakai untuk mencari dan mengelola sumber bahsul ilmi.''','Temukan dua sumber tentang strategi mengulang pelajaran. Utamakan penelitian atau pedoman universitas. Cantumkan tautan dan jelaskan satu alasan relevansi setiap sumber.','Saya menuliskan pertanyaan, membaca hasil, memilih satu klaim, lalu membuka rujukan yang terhubung dengan klaim tersebut.','perp')
feature('Research dan ruang kerja Projects',[['Research','Penelusuran bertahap untuk pertanyaan yang lebih luas.'],['Projects','Mengumpulkan pencarian, berkas, dan instruksi satu pekerjaan.'],['Penggunaan','Beri cakupan yang jelas, lalu periksa sumber laporan.']],'''Research dapat membantu ketika pertanyaan membutuhkan beberapa putaran pencarian. Kita bisa meminta tinjauan awal, membatasi bahasa sumber, dan menyebut rentang tahun jika itu relevan. Walaupun prosesnya lebih panjang, laporan akhirnya masih memerlukan pembacaan dan pemeriksaan.

Ruang kerja Projects membantu menyimpan pencarian serta bahan yang berhubungan. Dalam sebagian bahan lama Anda mungkin menemukan nama Spaces. Nama yang muncul dapat berbeda, sehingga kita mengikuti fungsi yang tersedia pada akun demonstrasi. Saya menghindari menjanjikan jumlah unggahan atau kuota tertentu karena ketentuan tersebut dapat berubah.

Untuk pekerjaan sederhana hari ini, kita cukup memakai satu pencarian biasa. Saya memperlihatkan gambaran bagaimana hasil tadi kelak dikelompokkan di bawah satu topik penelitian. Setelah itu peserta menyebutkan sumber mana yang ingin dibaca lebih lanjut dan apa alasannya. Pengorganisasian terasa berguna ketika memudahkan kita menemukan kembali bahan yang sudah dinilai.''','Susun peta awal bahan tentang satu topik belajar. Pisahkan penelitian, pedoman institusi, dan tulisan populer. Jelaskan keterbatasan pencarian dan informasi yang belum ditemukan.','Saya menunjukkan pilihan Research dan ruang kerja apabila tersedia, lalu membandingkan tujuan keduanya dengan pencarian biasa.','perp')
task('Eksplorasi Perplexity',5,['Cari dua sumber tentang satu kebutuhan belajar.','Buka salah satu sumber dan pilih satu kalimat yang didukungnya.','Simpan tautan serta satu catatan tentang kecocokannya.'],'dua tautan dan satu catatan pemeriksaan klaim.', '''Gunakan topik yang dekat dan cukup sempit agar lima menit kita terpakai untuk membaca. Misalnya, Anda ingin mengetahui cara membuat latihan mengingat kembali sesudah membaca. Sebutkan jenis sumber yang Anda inginkan.

Jangan habiskan seluruh waktu dengan mengubah kata pencarian. Setelah dua hasil yang masuk akal ditemukan, buka salah satunya. Baca bagian yang paling berkaitan dengan jawaban. Tuliskan apakah sumber mendukung klaim itu sepenuhnya, hanya sebagian, atau belum jelas.

Bila halaman tidak dapat dibuka, catat kendalanya dan pilih hasil lain. Kita belum mempunyai dasar untuk mengutip isi yang belum terbaca. Tidak perlu membuat kesimpulan luas dari dua sumber. Tujuan latihan ini adalah mengalami sendiri hubungan antara jawaban, rujukan, dan teks asal.''','Apa perbedaan yang Anda temukan antara ringkasan jawaban dan teks sumber?')
chap(5,'DeepSeek','Percakapan dan mode penalaran','Tujuan bab: menguji jawaban terhadap syarat yang jelas',old=20,notes='DeepSeek kita tempatkan sebagai bab singkat agar Anda mengenal pilihan aplikasi lain. Kita akan memakai tugas yang sudah dikenal, lalu memeriksa apakah jawabannya mematuhi batas yang diberikan. Mode berpikir dapat membantu pekerjaan bertahap, tetapi hasil akhirnya tetap perlu dibaca.')
feature('Mode penalaran dan pencarian',[['Percakapan','Untuk penjelasan dan penyusunan jawaban.'],['Mode penalaran','Untuk tugas yang membutuhkan beberapa pertimbangan.'],['Pencarian dan berkas','Gunakan bila fasilitasnya tersedia pada aplikasi.']],'''Nama model dan fasilitas aplikasi perlu dibedakan. Sebuah model dapat mendukung penalaran, sedangkan kemampuan mencari web atau menerima berkas bergantung juga pada aplikasi dan akses yang digunakan. Karena itu, kita melihat pilihan yang benar-benar tampil, bukan menebak dari nama produk.

Saya memakai tugas jadwal belajar karena syaratnya mudah diperiksa. Ada enam hari, tiga bab, dan empat puluh lima menit setiap hari. Kita dapat menilai hasil berdasarkan jumlah menit dan perhatian kepada bab yang sulit. Bila ada mode penalaran, saya menunjukkan cara memilihnya dan membaca hasil akhirnya.

Jangan menganggap jawaban yang lebih panjang selalu lebih baik. Kita memeriksa apakah seluruh syarat terpenuhi dan apakah pembagiannya dapat dilaksanakan. Jika satu hari melampaui batas, tunjukkan kesalahannya dengan jelas dan minta revisi. Membaca tampilan proses juga tidak memberi kita kepastian mengenai kesadaran atau pengalaman batin suatu sistem.''','Susun jadwal tiga bab selama enam hari. Batas setiap hari 45 menit. Bab kedua paling sulit. Jelaskan pembagian waktunya dan periksa kembali total menit setiap hari.','Saya menunjukkan pilihan mode yang tersedia, mengirim tugas, lalu memeriksa satu hari pada tabel jadwal dengan menghitung total menitnya.','deep')
task('Praktik DeepSeek',5,['Gunakan tugas jadwal yang sama seperti sebelumnya.','Periksa dua syarat: jumlah waktu dan bagian paling sulit.','Minta koreksi bila ada syarat yang terlewat.'],'satu hasil beserta dua syarat yang sudah diperiksa.', '''Buka DeepSeek jika dapat diakses. Gunakan tugas jadwal yang sama agar perbandingan kita cukup adil. Bila Anda mengubah seluruh tugas, kita akan kesulitan membedakan perubahan akibat aplikasi dan perubahan akibat instruksi.

Pilih dua syarat yang mudah diperiksa. Pertama, jumlah menit setiap hari. Kedua, perhatian kepada bab yang paling sulit. Anda dapat meminta jawaban berbentuk tabel, lalu menghitung satu atau dua baris secara mandiri.

Jika menemukan kesalahan, jangan hanya menulis bahwa jawabannya buruk. Sebutkan letak kesalahan dan batas yang dilanggar. Misalnya, hari ketiga berjumlah lima puluh menit padahal batasnya empat puluh lima. Minta perbaikan pada bagian itu. Bila seluruh syarat terpenuhi, jelaskan bagian mana yang membuat hasilnya dapat digunakan. Kita belajar menilai hasil secara konkret.''','Apakah jawaban memenuhi syarat yang Anda tetapkan, dan bagaimana Anda memastikannya?')
chap(6,'Claude','Membaca bahan dan menyunting draf','Tujuan bab: memperbaiki tulisan tanpa mengubah makna',old=18,notes='Claude menjadi aplikasi terakhir dalam rangkaian pengenalan ini. Kita memakai pengalaman sebelumnya untuk bekerja dengan paragraf dan bahan bacaan. Sesudah bab ini, kita berhenti berpindah aplikasi dan mempelajari satu rumus prompt yang bisa dipakai di semua alat tadi.')
feature('Berkas dan penjelasan teks',[['Bahan','Tempelkan paragraf atau lampirkan berkas yang relevan.'],['Pertanyaan','Tunjuk kalimat yang ingin dipahami atau diperbaiki.'],['Pemeriksaan','Bandingkan hasil dengan bahan semula.']],'''Ketika membaca teks bersama Claude, saya memberi bahan yang memang sedang dibahas. Kita dapat meminta penjelasan sebuah paragraf, pemetaan gagasan, atau perbandingan dua bagian. Pertanyaan yang menunjuk bagian tertentu akan lebih mudah diperiksa daripada permintaan umum tentang satu kitab penuh.

Misalnya, ada paragraf yang terasa padat. Saya meminta gagasan utamanya dijelaskan dengan bahasa yang lebih sederhana, sambil mempertahankan istilah khusus. Setelah jawaban muncul, kita melihat apakah pengecualian dan batas dalam paragraf masih terwakili.

Untuk bahan Arab, kita tidak perlu otomatis menerjemahkannya. Peserta di sini sudah bisa membaca Arab. Bantuan yang lebih berguna mungkin penjelasan hubungan antarkalimat atau pembedaan antara ucapan penulis dan penjelasan tambahan. Kita sebutkan kebutuhan itu secara langsung. Jika berkas tidak terbaca dengan baik, gunakan bagian pendek dan cocokkan hasil dengan halaman asal.''','Jelaskan hubungan gagasan dalam paragraf ini. Pertahankan istilah khusus. Pisahkan keterangan yang jelas tertulis dari penjelasan tambahan Anda. [Tempel paragraf.]','Saya menempelkan satu paragraf, mengajukan pertanyaan yang menunjuk bagian tertentu, lalu membandingkan penjelasan dengan teks semula.','claude')
feature('Projects dan Artifacts',[['Projects','Menyimpan bahan dan instruksi yang berkaitan dengan satu pekerjaan.'],['Artifacts','Menampilkan hasil tertentu pada ruang kerja tersendiri.'],['Revisi','Sebutkan bagian yang diubah dan unsur yang harus dipertahankan.']],'''Jika sebuah pekerjaan berulang atau berlangsung lama, Projects dapat membantu mengelompokkan bahan dan instruksi. Misalnya, Anda ingin menjaga istilah penelitian tetap konsisten selama menyunting beberapa bagian. Bahan yang relevan dapat dikelompokkan agar pekerjaan lebih mudah dilanjutkan.

Artifacts menyediakan ruang tersendiri untuk sebagian hasil yang dibuat bersama Claude, termasuk draf atau keluaran lain yang sesuai. Dalam dauroh ini, manfaat yang paling dekat adalah melihat satu hasil lalu memperbaikinya secara bertahap. Kita tidak harus menjelajahi seluruh kemungkinan teknisnya.

Saya memperlihatkan sebuah paragraf yang urutannya kurang jelas. Perintah revisinya saya batasi: perbaiki urutan penjelasan, pertahankan makna dan kutipan, lalu jelaskan perubahan. Sesudah itu kita baca hasilnya bersama. Kalau revisi membuat pendapat terdengar lebih pasti daripada bahan awal, kita minta dikembalikan. Kontrol seperti ini akan dipakai kembali pada bab penulisan bahsul ilmi.''','Rapikan urutan penjelasan pada draf ini. Pertahankan makna, istilah, dan kutipan. Setelah revisi, jelaskan perubahan yang Anda lakukan. [Tempel draf.]','Saya menunjukkan ruang proyek dan hasil berbentuk Artifact bila tersedia. Kita melakukan satu revisi terarah dan membaca perubahannya.','claude')
feature('Web search dan Research',[['Web search','Mencari informasi luar dan menampilkan rujukan.'],['Research','Penelusuran yang lebih luas pada akses yang mendukungnya.'],['Bahan penelitian','Teks, versi, dan lokasi sumber tetap dicatat.']],'''Claude juga menyediakan pencarian dan, pada akses yang mendukungnya, Research. Kita sudah mengenal gagasan penelusuran bertahap melalui aplikasi sebelumnya. Sekarang peserta melihat bahwa beberapa fungsi serupa muncul dengan nama dan tampilan yang berbeda.

Kita memilih alat berdasarkan tugas yang hendak dikerjakan. Jika pertanyaannya hanya tentang paragraf yang diberikan, pencarian luar mungkin belum diperlukan. Jika kita ingin menemukan penelitian yang belum ada dalam bahan, penelusuran menjadi relevan. Sebutkan perbedaannya dalam permintaan.

Hasil penelitian perlu tetap dihubungkan dengan sumber yang benar-benar dibaca. Saya meminta tautan dan alasan relevansi, kemudian membuka satu sumber. Bila fasilitas Research tidak tersedia, kita dapat mengikuti alur serupa secara manual melalui pencarian dan pembacaan. Peserta tidak perlu merasa tertinggal karena jenis akunnya berbeda. Yang kita latih adalah cara bekerja dengan jelas dan memeriksa hasilnya.''','Temukan bahan awal tentang topik ini. Utamakan sumber yang dapat dibuka. Jelaskan relevansi tiap sumber dan tandai informasi yang belum dapat dipastikan. [Sebutkan topik.]','Saya menunjukkan letak pencarian pada akun yang tersedia dan membuka satu rujukan. Untuk Research, saya jelaskan bahwa ketersediaannya perlu dilihat pada akun.','claude')
task('Praktik Claude',10,['Tempelkan paragraf sendiri yang boleh dibagikan.','Minta satu perbaikan pada urutan atau kejelasan kalimat.','Bandingkan hasil dan tandai perubahan makna bila ada.'],'paragraf sebelum dan sesudah revisi beserta satu keputusan Anda.', '''Pilih paragraf yang Anda pahami isinya. Jangan memakai teks yang sama sekali asing, karena kita akan menilai apakah hasil revisi mempertahankan makna. Paragraf boleh berbahasa Arab. Yang diperbaiki dapat berupa hubungan kalimat atau urutan penjelasan.

Sebelum mengirim, tentukan unsur yang harus dijaga. Misalnya istilah khusus, kutipan, nama penulis, atau kata yang menunjukkan ketidakpastian. Setelah hasil muncul, baca perlahan sambil melihat teks awal. Tandai satu perubahan yang membantu dan satu perubahan yang ingin Anda tanyakan.

Anda tidak wajib menerima seluruh hasil. Jika perbaikan terdengar lebih lancar tetapi mengubah maksud, tuliskan alasannya dan minta revisi lagi. Kita membiasakan diri mengambil keputusan sebagai pemilik tulisan. Hasil latihan ini akan menjadi contoh ketika besok kita membahas penyuntingan naskah penelitian.''','Perubahan mana yang Anda terima, dan perubahan mana yang perlu ditolak atau diperiksa?')
chap(7,'Prompt yang jelas','Rumus TEPAT','Tugas, Ekspektasi, Pembaca, Acuan, dan Tata batas',old=28,notes='Setelah mencoba beberapa aplikasi, kita sudah punya pengalaman yang cukup untuk membicarakan prompt dengan lebih teratur. Kita gunakan rumus TEPAT sebagai alat bantu ingatan dalam dauroh ini. Ini rumus pengajaran kita, bukan standar resmi atau jaminan bahwa AI selalu benar. Anda boleh memulai dari tugas singkat, lalu menambahkan unsur yang memang dibutuhkan.')
add('TEPAT',['T  Tugas: pekerjaan apa yang harus dilakukan?','E  Ekspektasi: hasil seperti apa yang Anda inginkan?','P  Pembaca: untuk siapa dan pada tingkat apa?','A  Acuan: bahan atau contoh apa yang dipakai?','T  Tata batas: apa yang harus dijaga atau dihindari?'],'''Kita pakai satu kata yang mudah diingat: TEPAT. Huruf pertama adalah Tugas. Katakan pekerjaannya, misalnya menjelaskan, merangkum, membandingkan, atau meninjau. Jangan berhenti pada menyebut topik, karena topik yang sama dapat dikerjakan dengan banyak cara.

E adalah Ekspektasi. Kita menentukan bentuk dan ukuran hasil yang diperlukan. Bisa berupa tabel singkat, penjelasan dua paragraf, atau daftar pertanyaan. P adalah Pembaca. Jelaskan siapa yang akan menggunakan hasil dan tingkat pengetahuannya. Ini membantu mengatur bahasa serta kedalaman penjelasan.

A adalah Acuan. Sertakan teks, data, atau contoh yang diperlukan. Bila tugasnya tentang bahan tertentu, acuan itu sangat penting. T terakhir adalah Tata batas. Kita menyebut unsur yang harus dipertahankan, informasi yang belum boleh disimpulkan, serta batas panjang atau cakupan.

Kelima unsur ini bukan kewajiban menulis prompt panjang setiap kali. Untuk tugas ringan, beberapa unsur dapat tersirat dari percakapan. Namun ketika hasilnya kurang tepat, periksa unsur mana yang belum jelas. Menulis “Anda adalah profesor terbaik” belum menggantikan bahan yang diperlukan. Kalimat yang tegas meminta ketidakpastian juga belum menjamin hasil benar. Kita tetap membaca dan memeriksa sumber yang dipakai.''','formula')
add('Satu prompt dengan lima unsur',['Tugas: jelaskan perbedaan topik dan pertanyaan penelitian.','Ekspektasi: dua contoh dan satu pertanyaan latihan.','Pembaca: mahasiswa akhir yang baru belajar riset.','Acuan: catatan kuliah yang saya tempelkan.','Tata batas: gunakan catatan ini dan tandai bagian yang kurang.'],'''Mari kita isi rumus tadi dengan satu tugas yang nyata. Pekerjaan yang ingin saya minta adalah menjelaskan perbedaan topik dan pertanyaan penelitian. Hasilnya saya tentukan: dua contoh dan satu pertanyaan latihan. Dengan begitu, AI mempunyai gambaran keluaran yang diharapkan.

Saya menyebut pembacanya, yaitu mahasiswa tingkat akhir yang baru belajar penelitian. Keterangan ini membantu AI menyesuaikan bahasa. Karena kita akan menggunakan catatan kuliah, saya menempelkan catatan tersebut sebagai acuan. Lalu saya membatasi jawaban agar tetap mengacu kepada bahan itu dan menandai bagian yang belum lengkap.

Kelima unsur dapat digabung menjadi satu paragraf biasa. Kita tidak harus mengetik huruf T, E, P, A, dan T setiap kali. Rumus ini berfungsi sebagai pemeriksaan sebelum mengirim. Jika hasilnya terlalu panjang, ekspektasinya perlu diperjelas. Jika bahasanya terlalu sulit, pembaca atau tingkat penjelasannya mungkin belum cukup jelas.

Saya meminta seorang peserta membaca prompt lengkap dengan suara biasa. Kita ingin kalimatnya tetap terasa seperti menjelaskan pekerjaan kepada rekan yang membantu. Setelah itu, peserta lain menunjukkan letak acuan dan tata batas. Perhatikan bahwa kita tidak meminta AI menulis penelitian lengkap. Kita memilih satu pekerjaan yang dapat diperiksa hasilnya.''','prompt',prompt='Jelaskan perbedaan topik dan pertanyaan penelitian untuk mahasiswa akhir yang baru belajar riset. Gunakan catatan berikut. Berikan dua contoh dan satu pertanyaan latihan. Gunakan hanya catatan ini dan tandai informasi yang kurang. [Tempel catatan.]')
reuse(29,'compare',title='Prompt kabur dan prompt yang lebih jelas',extra='Kita sekarang dapat menjelaskan perbedaannya memakai TEPAT. Pada contoh kedua, tugas dan batas waktu sudah lebih jelas. Jika hasilnya belum cocok, tambahkan acuan atau konteks pembaca. Jangan menambah kalimat hanya supaya prompt terlihat panjang.')
reuse(25,'workflow',title='Percakapan lanjutan',extra='Dalam TEPAT, unsur yang kurang dapat ditambahkan pada pesan lanjutan. Contohnya, kita menjelaskan acuan yang belum ada atau memperbaiki ekspektasi hasil. Kita mempertahankan bagian yang sudah baik dan memperjelas satu hal yang masih bermasalah.')
reuse(32,'workflow',title='Pekerjaan besar, langkah yang bisa diperiksa')
reuse(33,'checklist',title='Kesalahan yang perlu dikenali')
task('Praktik rumus TEPAT',15,['Tulis satu prompt untuk kebutuhan belajar atau penelitian Anda.','Periksa lima unsur TEPAT, lalu jalankan prompt.','Perbaiki satu unsur dan bandingkan hasilnya.'],'prompt awal, prompt revisi, dan satu alasan perubahan.', '''Kita menyediakan lima belas menit karena tugas ini menyatukan pengalaman dari beberapa aplikasi. Gunakan satu aplikasi yang dapat Anda akses dengan nyaman. Pilih pekerjaan kecil yang hasilnya dapat dinilai sekarang, misalnya memahami paragraf, menata catatan, atau membuat pertanyaan awal penelitian.

Sebelum mengirim, baca prompt Anda dan cari kelima unsur TEPAT. Tidak semua unsur harus panjang, tetapi setiap unsur yang memengaruhi hasil perlu jelas. Jika tugas membutuhkan bahan, sertakan bahan yang boleh dibagikan. Jika Anda belum punya bahan, pilih tugas yang memang tidak bergantung pada dokumen tertentu.

Setelah menerima hasil pertama, jangan mengubah semuanya. Pilih satu masalah yang paling nyata. Mungkin penjelasannya terlalu sulit, cakupannya terlalu luas, atau jawabannya menambahkan informasi di luar bahan. Perbaiki unsur yang terkait, kemudian jalankan lagi.''','Unsur TEPAT mana yang paling membantu memperbaiki hasil Anda?')
add('Pembahasan latihan TEPAT',['Sebelum: unsur yang belum jelas','Sesudah: satu perubahan yang sengaja dibuat','Keputusan: bagian hasil yang diterima atau masih diperiksa'],OLD[33]['notes']+'\n\nPada pembahasan ini, saya meminta peserta menyebutkan unsur TEPAT yang diubah. Kita menghindari penilaian bahwa suatu aplikasi selalu lebih baik hanya dari satu percobaan. Yang dibahas adalah hubungan antara instruksi, bahan, dan hasil tertentu.','compare')
reuse(40,'closing',title='Bekal untuk hari kedua')
# DAY TWO
DAY1=len(S);day=2;chapter='Pembukaan hari kedua';bab=0
add('Hari kedua',['AI dalam pekerjaan bahsul ilmi','Bahan yang dipakai hari ini berasal dari sumber yang dapat diperiksa.'],OLD[40]['notes'],'cover')
add('Urutan kerja hari ini',['Pengumpulan sumber dan penyimpanan bahan','Rancangan penelitian dan penelitian terdahulu','Pembacaan, metode, penulisan, serta revisi','Praktik akhir dan tur proyek OpenTurath'],OLD[41]['notes'],'agenda')
chap(8,'Mengumpulkan sumber','Di mana bahan ditemukan dan bagaimana menyimpannya?','Telegram, Internet Archive, Noor Book, perpustakaan kitab, dan situs ilmiah',notes='''Hari kedua kita mulai dari pengumpulan bahan. Sebelum meminta AI membahas sebuah masalah, kita perlu tahu sumber apa yang dipakai dan bagaimana sumber itu diperoleh. Ini bagian yang sering terasa melelahkan, karena judul, cetakan, nama berkas, dan nomor halaman bisa berbeda-beda.

Kita akan menggunakan beberapa pintu pencarian. Telegram dapat menjadi tempat menemukan kabar terbit atau berkas yang dibagikan. Internet Archive dan Noor Book membantu menelusuri buku. Syamilah membantu pencarian teks, sementara perpustakaan seperti Waqfeya membantu mencari salinan cetak digital. Untuk artikel dan tesis, kita juga memerlukan situs jurnal atau repositori universitas.

Setiap pintu mempunyai fungsi dan keterbatasan. Menemukan berkas belum berarti kita sudah memastikan edisi dan kelengkapannya. Kita akan membuka halaman judul, melihat data penerbitan, dan mencatat lokasi bahan. Setelah itu barulah bantuan AI terhadap isi sumber lebih mudah diperiksa.

Saya ingin peserta mengakhiri bab ini dengan satu sumber yang nyata, bukan folder berisi puluhan berkas yang belum dibuka. Kita akan menyimpan bahan itu dengan identitas yang jelas. Jika sumber tidak bisa diakses, catat jalur pencarian dan kendalanya agar pekerjaan dapat dilanjutkan secara terarah.''')
add('Peta tempat mencari bahan',[['Buku dan cetakan','Internet Archive, Noor Book, Waqfeya'],['Teks yang dapat dicari','Syamilah dan perpustakaan teks lain'],['Artikel dan tesis','Jurnal, repositori universitas, dan mesin pencarian ilmiah'],['Informasi serta berkas','Kanal Telegram milik lembaga, penerbit, atau pengelola perpustakaan']],'''Sebelum mencari, tentukan bentuk bahan yang dibutuhkan. Jika Anda memerlukan kalimat persis beserta nomor halaman edisi tertentu, salinan cetak digital mungkin paling penting. Jika Anda sedang mencari kemunculan satu istilah di banyak kitab, perpustakaan teks dapat membantu menemukan lokasi awal.

Penelitian terdahulu memerlukan jalur yang berbeda lagi. Kita mencari artikel, tesis, atau disertasi melalui situs jurnal dan repositori. Nama sebuah artikel yang muncul pada jawaban AI dapat menjadi petunjuk, tetapi kita masih perlu menemukan rekaman atau naskah aslinya.

Telegram berguna sebagai jalur penemuan dan pembaruan. Misalnya, penerbit mengumumkan buku baru atau perpustakaan membagikan tautan koleksi. Setelah menemukan informasi itu, kita kembali kepada identitas buku dan sumber yang bisa ditelusuri. Jumlah pelanggan kanal tidak menetapkan kualitas ilmiah sebuah berkas.

Saya meminta peserta memilih satu kebutuhan nyata, lalu menyebut tempat pertama yang paling masuk akal untuk mencarinya. Kita tidak perlu membuka semua situs untuk setiap pekerjaan. Mulailah dari sumber yang paling dekat dengan bahan yang diperlukan. Jika belum berhasil, perluas pencarian sambil mencatat kata kunci yang sudah dicoba.''','compare',refs=REF['sources'])
add('Telegram: alur pencarian bahan',['Pencarian umum: judul kitab, nama pengarang, atau bidangnya.','Pencarian dalam kanal: kata judul, nama muhaqqiq, penerbit, atau “PDF”.','Pemeriksaan berkas: halaman judul, cetakan, jilid, dan kelengkapan.','Penyimpanan: catat tautan unggahan bersama berkas yang dipakai.'],'''Di Telegram, kita bisa mulai dari pencarian umum untuk menemukan kanal yang berkaitan dengan bidang atau judul tertentu. Setelah masuk ke sebuah kanal, pencarian di dalam kanal membantu mempersempit hasil. Gunakan judul pendek, nama pengarang, nama muhaqqiq, atau nama penerbit secara bergantian.

Kalau satu judul mempunyai beberapa cetakan, jangan berhenti pada nama berkas. Buka berkas dan lihat halaman judul serta data penerbitan. Pastikan jilid yang dibutuhkan ada dan halaman yang akan digunakan cukup terbaca. Nama berkas bisa dibuat oleh pengunggah dan belum tentu menggambarkan edisinya dengan tepat.

Saya menunjukkan contoh alur pencarian tanpa meminta peserta mengikuti kanal secara otomatis. Kita membedakan kanal lembaga yang dapat dilacak melalui situsnya dengan kanal yang identitas pengelolanya belum jelas. Jika bahan tersedia melalui tautan resmi penerbit atau lembaga, simpan jalur tersebut juga.

Ketika memperoleh berkas, catat asalnya. Tautan unggahan, nama kanal, dan tanggal akses membantu kita menemukan kembali bahan, tetapi catatan bibliografi tetap berasal dari identitas buku. Kita menggunakan bahan yang memang boleh diakses dan dibagikan. Untuk kutipan akhir, sumbernya adalah buku atau artikel yang dibaca, sementara Telegram dicatat sebagai jalur perolehannya bila diperlukan.''','workflow',refs=['https://telegram.org/faq','https://t.me/s/shamelaws'])
add('Kanal Telegram yang relevan',['Contoh yang ditelusuri: @shamelaws, kanal yang memakai nama situs Syamilah.','Kanal lembaga atau penerbit: buka tautannya dari situs resmi pengelola.','Kanal bidang khusus: pilih sesuai topik, lalu periksa identitas dan contoh berkas.','Catatan pencarian: nama kanal, tautan, fokus koleksi, dan hasil pemeriksaan.'],'''Daripada memberi daftar panjang kanal yang belum kita periksa, kita mulai dengan satu contoh yang dapat ditelusuri. Kanal dengan alamat shamelaws memuat unggahan yang mengarah ke situs Syamilah. Peserta dapat melihat bagaimana sebuah kanal memberi kabar pembaruan dan tautan bahan.

Untuk mencari kanal lain, saya menyarankan berangkat dari lembaga atau penerbit yang Anda kenal. Buka situs resminya dan lihat apakah ada tautan Telegram. Cara ini membantu mengurangi kebingungan akibat nama dan logo yang mirip. Jika tautan resmi belum ditemukan, jangan langsung memberi label resmi kepada kanal itu.

Kanal bidang khusus dapat berguna, misalnya untuk kajian hadis, usul fikih, atau manuskrip. Namun relevansi isinya perlu dinilai dari contoh unggahan dan identitas bahan. Kita juga memeriksa apakah keterangannya lengkap dan apakah tautannya masih dapat dibuka.

Dalam latihan, peserta mencatat satu kanal yang relevan dan satu alasan pemilihannya. Jika identitas kanal belum pasti, tulis bahwa statusnya belum terverifikasi. Kita tidak memerlukan klaim bahwa kanal itu paling lengkap. Yang kita perlukan adalah jalur kerja yang dapat dijelaskan dan satu bahan yang dapat diperiksa. Rekomendasi kanal tambahan dapat diperbarui setelah pengajar memeriksa contoh unggahan serta hubungan kanal dengan pengelolanya.''','checklist',refs=['https://t.me/s/shamelaws','https://shamela.ws/'])
add('Internet Archive',[['Alamat','archive.org'],['Pencarian','Coba judul, pengarang, dan variasi penulisan Arab.'],['Pemilihan','Buka halaman item dan baca keterangan koleksinya.'],['Pemakaian','Periksa salinan yang dapat diakses dan simpan tautan item.']],'''Situs yang kita maksud adalah Internet Archive dengan alamat archive.org. Kita mulai dari pencarian judul atau pengarang. Jika hasilnya tidak muncul, coba bentuk judul yang lebih pendek atau variasi penulisan nama. Tidak semua pengunggah menulis metadata dengan cara yang sama.

Ketika halaman item terbuka, baca keterangannya terlebih dahulu. Lihat judul, pengarang, dan informasi yang tersedia tentang penerbitan. Kemudian buka pembaca buku atau berkas yang memang tersedia untuk diakses. Akses baca, peminjaman, dan unduhan dapat berbeda pada setiap item.

Saya ingin peserta melihat halaman judul serta satu halaman isi. Pada buku berjilid, periksa jilid mana yang sedang dibuka. Nomor halaman pada pembaca digital dapat berbeda dari nomor yang tercetak dalam buku. Catat nomor cetak yang diperlukan untuk kutipan, dan tambahkan lokasi digital sebagai alat bantu bila berguna.

Simpan tautan halaman item bersama catatan sumber. Jika salinan tidak lengkap atau kurang terbaca, tandai masalahnya sebelum mencari edisi lain. Kita tidak menganggap sebuah item pasti paling baik hanya karena muncul lebih dahulu pada hasil pencarian. Pilihan edisi mengikuti kebutuhan penelitian dan pertimbangan ilmiah yang dapat dijelaskan.''','feature',refs=['https://archive.org/'])
add('Noor Book',[['Alamat','noor-book.com'],['Pencarian','Judul, nama penulis, atau kategori buku.'],['Halaman buku','Bedakan keterangan katalog dengan berkas yang tersedia.'],['Unduhan','Hanya sebagian bahan tersedia untuk diunduh sesuai ketentuannya.']],'''Noor Book dapat dipakai untuk mencari judul, penulis, dan informasi buku. Kita membuka halaman buku untuk melihat apakah ada berkas yang dapat diakses atau halaman itu hanya memuat keterangan dan ulasan. Keberadaan sebuah judul di katalog belum berarti unduhannya tersedia.

Saya meminta peserta memperhatikan identitas buku, bukan hanya sampulnya. Sampul yang mirip dapat digunakan pada edisi yang berbeda. Jika berkas tersedia, halaman judul dan data cetakan tetap kita periksa setelah membukanya. Informasi yang belum ditemukan diberi tanda supaya tidak terisi dengan dugaan.

Situs menjelaskan bahwa bahan yang tersedia untuk unduhan gratis dapat diunduh tanpa pembayaran. Namun beberapa judul mempunyai pembatasan akses atau hak. Karena itu, kita mengikuti pilihan akses yang diberikan pada halaman terkait dan tidak menjanjikan bahwa seluruh judul dapat diunduh.

Untuk latihan, pilih satu buku yang berkaitan dengan topik Anda. Catat judul, pengarang, tautan, dan apakah teksnya sudah berhasil dibuka. Jika hanya ada halaman katalog, gunakan itu sebagai petunjuk pencarian berikutnya. Bahan untuk kutipan akhir sebaiknya berasal dari naskah yang telah Anda baca sendiri, dengan identitas versi yang cukup jelas untuk diperiksa pembaca.''','feature',refs=['https://www.noor-book.com/contact-us'])
add('Syamilah dan Waqfeya',[['Syamilah','Membantu menelusuri kata dan membaca teks kitab.'],['Waqfeya','Membantu mencari serta membuka salinan buku.'],['Pemakaian bersama','Temukan lokasi teks, lalu cocokkan dengan edisi yang dipakai.']],'''Syamilah membantu kita mencari kata atau ungkapan dalam koleksi teks. Ini sangat berguna untuk menemukan tempat awal pembahasan. Kita dapat mencoba beberapa kata yang berkaitan dengan masalah, lalu membaca bagian yang muncul dalam konteksnya.

Waqfeya menyediakan penelusuran buku menurut berbagai kategori dan identitas penulis. Jika salinan yang sesuai ditemukan, kita membuka halaman judul dan bagian yang diperlukan. Dengan begitu, pencarian teks dan pemeriksaan salinan cetak dapat saling membantu.

Kita tetap harus mencatat edisi masing-masing. Nomor halaman yang disebut pada teks digital belum tentu sama dengan berkas PDF yang sedang Anda pakai. Jika ada keterangan bahwa penomorannya sesuai cetakan, cocokkan dengan cetakan yang dimaksud. Jangan memindahkan nomor halaman secara otomatis ke edisi lain.

Saya memperlihatkan satu contoh pencarian istilah, kemudian meminta peserta membaca kalimat sebelum dan sesudahnya. Kita ingin mengetahui siapa yang berbicara dan dalam pembahasan apa kalimat itu muncul. Setelah itu, barulah kita memutuskan apakah bagian tersebut relevan dengan pertanyaan penelitian. Kecepatan menemukan kata membantu pekerjaan, sedangkan pemahaman isi tetap memerlukan pembacaan yang teliti.''','compare',refs=['https://shamela.ws/','https://www.waqfeya.net/'])
add('Artikel, tesis, dan repositori',['Mesin pencarian ilmiah membantu menemukan judul dan pengarang.','Situs jurnal memberi metadata, abstrak, dan naskah jika tersedia.','Repositori universitas membantu menelusuri tesis atau disertasi.','Kata kunci perlu dicoba dalam beberapa bentuk dan bahasa.'],'''Jika yang kita cari adalah penelitian terdahulu, jangan membatasi pencarian pada perpustakaan kitab. Kita memerlukan artikel, tesis, dan disertasi yang membahas masalah berkaitan. Mulailah dengan istilah inti, lalu tambahkan variasi yang dipakai dalam bidang tersebut.

Mesin pencarian ilmiah dapat membantu menemukan judul dan pengarang. Setelah menemukan hasil, buka situs jurnal atau repositori yang menyimpan rekamannya. Catat metadata yang tersedia dan apakah naskah lengkap berhasil dibuka. Keterangan dari abstrak harus dibedakan dari isi keseluruhan penelitian.

Pada topik Arab, judul dapat memakai istilah yang berbeda meskipun persoalannya berdekatan. Karena itu, coba kata yang lebih umum dan kata yang lebih khusus. Nama tokoh, kitab, mazhab, atau periode dapat ditambahkan jika sesuai dengan pertanyaan penelitian.

AI boleh membantu mengusulkan variasi kata kunci. Namun daftar artikel yang disebut AI belum kita perlakukan sebagai daftar sumber yang terverifikasi. Temukan rekaman aslinya dan buka bahan yang dapat diakses. Jika sebuah naskah belum tersedia, tandai keterbatasan itu. Kita tetap dapat menyusun rencana pembacaan tanpa mengaku sudah membaca penelitian yang baru diketahui judulnya.''','workflow',refs=['https://scholar.google.com/'])
add('Sebelum sebuah berkas menjadi sumber',['Identitas: judul, pengarang, muhaqqiq, penerbit, dan tahun.','Kelengkapan: jilid, awal dan akhir buku, serta halaman yang diperlukan.','Keterbacaan: teks cetak, pindai, atau hasil pengenalan huruf.','Lokasi: halaman cetak dan tautan atau jalur berkas.'],OLD[51]['notes']+'\n\nPemeriksaan ini dilakukan terhadap berkas yang benar-benar digunakan. Saya membuka halaman judul dan satu halaman isi, lalu mencatat informasi yang tersedia. Jika muhaqqiq atau tahun tidak ditemukan, kolom itu dibiarkan bertanda belum diketahui. Kita tidak menyimpulkan data bibliografi dari tebakan nama berkas.','checklist')
add('Folder dan kartu sumber',[['Nama berkas','Pengarang_Judul_Edisi_Jilid.pdf'],['Folder sederhana','Sumber, catatan, draf, dan hasil revisi.'],['Kartu sumber','Identitas buku, tautan, halaman relevan, dan catatan pemeriksaan.'],['Status','Sudah dibaca, baru ditemukan, atau masih perlu diperiksa.']],'''Sumber yang berhasil ditemukan perlu disimpan supaya mudah digunakan kembali. Kita dapat memakai nama berkas yang cukup jelas, misalnya nama pengarang, judul singkat, edisi, dan jilid. Hindari mengganti nama sehingga data penting justru hilang.

Pisahkan sumber asli dari catatan dan draf tulisan. Dengan begitu, kita tidak keliru mengira ringkasan buatan sendiri sebagai teks sumber. Untuk setiap bahan, buat satu kartu singkat yang berisi identitas, tautan perolehan, halaman yang berkaitan, dan masalah yang masih perlu diperiksa.

Status pembacaan juga penting. Ada bahan yang baru ditemukan, ada yang baru dibaca abstraknya, dan ada yang sudah diperiksa bagian isinya. Menuliskan status membantu kita jujur terhadap kemajuan pekerjaan. Kita tidak perlu memaksa seluruh bahan terlihat selesai.

AI bisa membantu merapikan metadata yang Anda tempelkan atau membuat susunan kartu sumber. Berikan informasi yang benar-benar ada, lalu minta bagian kosong tetap ditandai. Sesudah hasil dibuat, cocokkan kembali dengan halaman buku. Cara kerja ini akan memudahkan saat menulis daftar pustaka, membandingkan penelitian terdahulu, dan menjawab pertanyaan tentang sumber yang digunakan.''','workflow')
task('Praktik pengumpulan sumber',15,['Cari satu bahan melalui situs atau kanal yang relevan.','Buka teks atau rekaman sumber, lalu periksa identitasnya.','Buat kartu sumber dan catat bagian yang belum diketahui.'],'satu kartu sumber dengan tautan dan status pembacaan yang jujur.', '''Pilih satu bahan yang memang ingin Anda baca. Boleh kitab, artikel, atau tesis. Tentukan dahulu jenisnya agar tempat pencarian tidak asal dipilih. Bila mulai dari Telegram, catat jalur unggahannya. Bila mulai dari situs, simpan halaman item atau rekaman sumbernya.

Setelah menemukan hasil, buka sumber yang tersedia dan lihat identitasnya. Kita tidak sedang berlomba mengunduh sebanyak mungkin. Satu sumber yang cukup jelas lebih berguna untuk latihan daripada banyak berkas yang belum dikenali. Periksa satu halaman yang berkaitan dengan topik Anda.

Buat kartu sederhana: judul, pengarang, data edisi yang ditemukan, tautan, halaman relevan, serta status pembacaan. Informasi yang belum diketahui diberi tanda. Bila teks belum dapat dibuka, catat itu dengan jelas dan gunakan rekaman katalog sebagai petunjuk lanjutan.''','Apakah orang lain dapat menemukan kembali sumber yang Anda pakai dari catatan tersebut?')
add('Pembahasan kartu sumber',['Apa yang sudah berhasil dipastikan?','Apa yang masih berupa dugaan atau informasi kosong?','Langkah berikutnya: membaca bagian relevan atau mencari versi lain.'],OLD[59]['notes']+'\n\nSaya memilih dua kartu sumber dari peserta. Kita membaca identitas dan statusnya, lalu melihat apakah tautan atau lokasi cukup jelas. Fokus pembahasan adalah ketertelusuran dan kesesuaian bahan dengan pertanyaan. Bila ada kolom kosong, kita tentukan langkah untuk melengkapinya tanpa menebak.','compare')
chap(9,'Rancangan dan penelitian terdahulu','Apa yang ingin diteliti dan apa yang sudah dibahas?','Topik, pertanyaan, batas penelitian, dan pembacaan penelitian terdahulu',old=42,notes='Sekarang kita sudah mempunyai gambaran tempat mencari sumber. Kita kembali kepada pertanyaan penelitian agar pengumpulan bahan tetap terarah. Sumber awal dapat membantu mempersempit topik, sementara pertanyaan yang lebih jelas membantu pencarian berikutnya. Kedua pekerjaan ini dapat berlangsung bolak-balik.')
for n,k in [(43,'definition'),(44,'compare'),(45,'compare'),(46,'definition'),(47,'rows'),(48,'exercise'),(49,'workflow'),(50,'compare'),(52,'checklist'),(53,'rows'),(54,'compare'),(55,'quote')]:reuse(n,k)
chap(10,'Membaca dan mengolah bahan','Bagaimana AI membantu tanpa mengaburkan sumber?','Penjelasan teks, ringkasan, perbandingan, dan catatan bacaan',old=35,notes='Pada bab ini, kita memakai sumber yang sudah ditemukan. Kita akan menunjuk bagian tertentu, memberi pertanyaan yang jelas, lalu mencatat hasil yang dapat dilacak kembali ke halaman asal. Untuk teks Arab, bantuan tidak selalu berbentuk terjemahan. Kita bisa meminta hubungan gagasan atau penjelasan istilah dalam konteksnya.')
for n,k in [(36,'compare'),(56,'prompt'),(57,'workflow'),(58,'compare'),(59,'definition'),(60,'workflow')]:reuse(n,k)
add('Istirahat',['15 menit','Simpan kartu sumber dan catatan bacaan sebelum melanjutkan.'],'''Kita berhenti lima belas menit sebelum masuk ke metode dan penulisan. Simpan kartu sumber dan catatan bacaan yang sudah dibuat. Jika ada bagian yang belum selesai, cukup beri tanda agar Anda tahu dari mana melanjutkan.

Sampai di sini, rangkaian kerja kita sudah mulai terlihat. Pertanyaan membantu menentukan bahan yang dicari, bahan yang ditemukan membantu memperjelas pertanyaan, lalu pembacaan menghasilkan catatan yang dapat dipakai untuk menulis. Kita tidak perlu menyelesaikan penelitian penuh dalam satu sesi ini.

Sesudah istirahat, kita akan menghubungkan catatan tadi dengan pilihan metode, susunan bab, dan paragraf pembahasan. Perhatikan bahwa keputusan penelitian tetap perlu Anda pahami. Nama metode yang terdengar ilmiah belum cukup jika langkah kerjanya belum jelas.

Gunakan jeda ini untuk memastikan berkas asli dan hasil ringkasan tersimpan terpisah. Kita akan menggunakan sebagian catatan setelah kembali. Bila akses internet kurang baik, lanjutkan dengan bahan yang sudah terbuka atau kerjakan bersama teman. Tujuan pembelajaran tetap dapat dicapai melalui pemeriksaan satu bagian yang jelas, tanpa harus membuka banyak aplikasi sekaligus. Setelah waktu istirahat selesai, saya meminta peserta menyiapkan satu catatan bacaan untuk menjadi bahan penulisan.''','break')
chap(11,'Metode, penulisan, dan revisi','Bagaimana bahan menjadi pembahasan yang dapat dipertanggungjawabkan?','Metode, kerangka, analisis, draf, kesimpulan, dan rujukan',old=61,notes='Kita akan membawa bahan yang telah dibaca ke dalam susunan penelitian. Bantuan AI perlu mengikuti pekerjaan yang benar-benar dilakukan. Kita boleh meminta pilihan susunan atau kritik, tetapi tetap harus memahami mengapa metode dan urutan pembahasannya sesuai dengan pertanyaan.')
for n,k in [(62,'compare'),(63,'workflow'),(64,'exercise'),(65,'workflow'),(66,'compare'),(67,'rows'),(68,'definition'),(69,'prompt'),(70,'exercise'),(71,'compare'),(72,'checklist'),(73,'rows'),(74,'workflow'),(75,'checklist'),(76,'quote')]:reuse(n,k)
reuse(79,'exercise',title='Praktik akhir: satu bagian bahsul ilmi',extra='Alokasikan lima belas menit. Hasil minimum adalah satu pertanyaan penelitian, satu kartu sumber, satu catatan bacaan, dan satu paragraf yang Anda pahami. Gunakan TEPAT ketika meminta bantuan. Pada akhir waktu, peserta menjelaskan satu keputusan yang mereka ambil sendiri. Jangan menambah kutipan atau nomor halaman yang belum diperiksa.')
chap(12,'Tur OpenTurath','Proyek untuk membantu perjalanan penuntut ilmu','OpenTurath AI, Maktabah, Manuskrip, dan dauroh',old=77,notes='Kita menutup dauroh dengan melihat proyek OpenTurath melalui pekerjaan yang baru saja dipraktikkan. Kita membedakan fungsi setiap proyek dan statusnya. Bagian yang masih dikembangkan akan disebut demikian. Saya akan menunjukkan alur yang dapat digunakan sekarang, lalu menjelaskan arah pengembangan tanpa menjanjikan fasilitas yang belum tersedia.')
add('OpenTurath AI',[['Kebutuhan','Membantu menelaah bahan dalam bidang ilmu tertentu.'],['Contoh ruang kajian','Fikih Syafi’i dan Fikih Tahawwulat.'],['Alur demonstrasi','Pertanyaan, jawaban, rujukan yang dibuka, lalu catatan peneliti.']],OLD[77]['notes']+'\n\nPada tur ini saya memperlihatkan aplikasi yang benar-benar dapat dibuka. Saya memilih satu pertanyaan kecil dan menunjukkan bagaimana hasilnya dibaca bersama sumber yang tersedia. Nama ruang kajian tidak menjadi jaminan bahwa seluruh kitab atau seluruh persoalan telah terwakili. Jika sebuah fungsi belum tersedia pada akses demonstrasi, saya menjelaskan batasnya secara langsung.','feature',refs=['workspace:openturath_ai/lib','workspace:website/src/pages.mjs'])
add('Maktabah OpenTurath',[['Fokus proyek','Memudahkan penemuan kitab dan pemilihan cetakan.'],['Manfaat yang dituju','Menghubungkan informasi buku dengan sumber salinan yang dapat dibuka.'],['Dalam tur','Tunjukkan bagian yang sudah berjalan dan bedakan dari rencana.']],'''Setelah melihat OpenTurath AI, kita beralih ke kebutuhan yang sudah kita alami pada bab sumber: menemukan kitab dan memilih cetakan yang tepat. Maktabah OpenTurath diarahkan untuk membantu pekerjaan tersebut. Gagasannya adalah membuat informasi buku dan jalur ke salinannya lebih mudah ditelusuri.

Dalam penelitian, satu judul dapat memiliki beberapa edisi. Karena itu, kemudahan pencarian perlu disertai identitas cetakan yang jelas. Kita ingin pengguna mengetahui apa yang sedang dibuka, bukan hanya menemukan berkas dengan nama yang mirip. Hubungan antara judul, edisi, dan salinan menjadi bagian penting dari pekerjaan ini.

Saat memperlihatkan proyek, saya membedakan bagian yang sudah bisa digunakan dari bagian yang masih dikembangkan. Jika belum ada layanan yang dapat dibuka peserta, saya cukup menunjukkan tujuan dan contoh alur yang direncanakan. Saya tidak menyebut seolah seluruh koleksi atau integrasinya sudah tersedia.

Kaitannya dengan latihan kita sangat dekat. Anda sudah membuat kartu sumber dan memeriksa identitas berkas. Maktabah diarahkan untuk mengurangi waktu pencarian awal, sementara keputusan memilih edisi dan menilai sumber tetap mengikuti kebutuhan penelitian. Pertanyaan dari peserta tentang edisi yang sulit ditemukan dapat dicatat sebagai masukan pengembangan, bukan janji bahwa setiap permintaan langsung tersedia.''','definition',refs=['workspace:website/redesign-v7/site/id/ekosistem.html'])
add('OpenTurath Manuskrip',[['Fokus proyek','Penyalinan naskah Arab menjadi teks yang bisa diperiksa.'],['Bagian penting','Mempertahankan bacaan dan menandai bagian yang belum jelas.'],['Hasil kerja','Teks digital yang tetap dibandingkan dengan gambar naskah.']],'''Proyek berikutnya berkaitan dengan bahan yang lebih sulit dicari teksnya, yaitu manuskrip atau halaman tulisan tangan. OpenTurath Manuskrip diarahkan untuk membantu penyalinan bahan Arab menjadi teks digital yang bisa dicari dan disunting. Pekerjaan awal ini dapat memakan waktu cukup lama bila dilakukan seluruhnya secara manual.

Saya ingin membedakan penyalinan dengan penetapan bacaan ilmiah. Jika satu kata belum jelas, bagian tersebut perlu ditandai. Kita tidak ingin kelancaran hasil digital menutupi ketidakpastian pada gambar asal. Nama, angka, dan bentuk huruf yang mirip harus dibandingkan dengan naskah.

Dalam tur, saya menunjukkan contoh halaman dan hasil yang memang telah diperiksa, bila tersedia. Kita melihat satu bagian yang terbaca dan satu bagian yang masih membutuhkan keputusan. Peserta akan lebih mudah memahami manfaat proyek melalui contoh kecil daripada klaim mengenai seluruh jenis tulisan tangan.

Setelah teks digital tersedia, pekerjaan ilmiah masih berlanjut. Peneliti dapat membandingkan saksi naskah, menelusuri rujukan, dan membuat keputusan tahqiq sesuai kompetensinya. Bantuan penyalinan mengurangi beban awal, sementara pertanggungjawaban bacaan tetap memerlukan pemeriksaan. Jika demonstrasi layanan belum tersedia, saya menjelaskan fungsi dan batasnya berdasarkan bahan contoh yang dapat ditunjukkan.''','definition',refs=['workspace:website/manuskrip/index.html'])
add('Dauroh dan pengembangan keterampilan',[['Yang dipraktikkan sekarang','Menggunakan AI, menyusun prompt, dan memeriksa sumber.'],['Kelanjutan belajar','Latihan berkala dengan bahan sendiri dan pembimbing.'],['Arah pengembangan','Bahan ajar serta alat yang menjawab kebutuhan penuntut ilmu.']],'''Dauroh ini juga merupakan bagian dari ikhtiar OpenTurath. Tujuannya agar penuntut ilmu mempunyai keterampilan yang dapat dipakai setelah acara selesai. Anda telah mencoba beberapa alat, menyusun permintaan, mengumpulkan sumber, dan meninjau bagian tulisan.

Keterampilan ini akan lebih kuat melalui latihan berulang pada pekerjaan yang memang Anda jalankan. Misalnya, setiap pekan Anda memilih satu paragraf untuk dipahami atau satu catatan untuk dirapikan. Sesudah menggunakan AI, catat bagian yang membantu dan bagian yang masih harus ditanyakan kepada pengajar.

Pengembangan bahan ajar berikutnya dapat menanggapi kebutuhan yang muncul dari latihan tersebut. Kita tidak harus langsung memakai semua alat atau mengikuti semua bidang teknologi. Lebih baik mengenali satu pekerjaan yang dapat dibantu secara jelas, lalu meningkatkan cara menilai hasilnya.

Saya mengajak peserta melihat hubungan antarproyek. Dauroh membantu kebiasaan penggunaan, Maktabah diarahkan untuk penemuan sumber, Manuskrip membantu penyalinan bahan tertentu, dan OpenTurath AI membantu penelaahan. Status masing-masing perlu disebutkan sesuai keadaan yang dapat ditunjukkan. Dengan demikian, tur proyek memberi gambaran yang jujur tentang manfaat yang ada dan arah pekerjaan yang masih berjalan.''','rows',refs=['workspace:website/redesign-v7/site/id/ekosistem.html'])
add('Tur singkat: satu kebutuhan nyata',['Kebutuhan peserta: memahami satu persoalan dari bahan tertentu.','Demonstrasi: pilih alat atau proyek yang sesuai dan tersedia.','Pemeriksaan: buka sumber, lihat hasil, lalu catat batasnya.','Penutup: satu pertanyaan lanjutan untuk dibawa belajar.'],OLD[77]['notes']+'\n\nKita menyediakan sekitar lima menit untuk tur terarah ini. Saya memilih satu kebutuhan peserta agar demonstrasi mempunyai tujuan yang jelas. Saya hanya menunjukkan bagian yang sudah dapat digunakan. Jika langkah tertentu masih berupa arah pengembangan, saya menyebutkannya sebelum berpindah ke proyek lain.','workflow')
reuse(80,'closing',title='Rencana setelah dauroh',extra='Sebelum selesai, setiap peserta menulis satu pekerjaan yang akan dicoba pekan ini. Gunakan rumus TEPAT, simpan sumber dan hasilnya, lalu catat satu pertanyaan untuk pembimbing. Ini menjadi tindak lanjut yang dapat dilakukan tanpa harus berlangganan seluruh aplikasi yang diperkenalkan.')
